from sk import *
from common import GL,CL,lrow,filt
import random; random.seed(7)
QS=['common','unc','rare','epic','common','unc','rare','poor','leg']
def slots(n,cols,sz=36,gap=4,empty=0.15):
    h=f'<div style="display:grid;grid-template-columns:repeat({cols},{sz}px);gap:{gap}px">'
    for i in range(n):
        if random.random()<empty: h+=f'<span style="width:{sz}px;height:{sz}px;border-radius:6px;background:#0b0c10;border:1px solid #23262e;display:inline-block"></span>'
        else: h+=ic(random.choice(GL+['potion_ball','health_potion','gold_bar','scroll_unfurled','anvil','diamond_hard']),random.choice(CL),sz,q=random.choice(QS),n=random.choice(['','','','5','20','2']))
    return h+'</div>'
